INSERT INTO `faqs` (`id`, `question`, `answer`, `category`, `sort_order`, `is_published`, `translations`, `created_at`, `updated_at`) VALUES ('1', 'Who can attend Europe Revival 2026?', 'Europe Revival is open to everyone—believers, seekers, church leaders, and anyone hungry for an encounter with God. Whether you''re a seasoned minister or new to faith, you''re welcome to join us in Budapest.', 'general', '1', '1', NULL, '2026-01-27 13:55:25', '2026-01-27 13:55:25');
INSERT INTO `faqs` (`id`, `question`, `answer`, `category`, `sort_order`, `is_published`, `translations`, `created_at`, `updated_at`) VALUES ('2', 'Will there be a livestream available?', 'Yes! Main sessions will be livestreamed for those who cannot attend in person. However, we highly encourage in-person attendance to fully experience the atmosphere of revival and receive personal ministry.', 'general', '3', '1', NULL, '2026-01-27 13:55:25', '2026-02-20 15:24:46');
INSERT INTO `faqs` (`id`, `question`, `answer`, `category`, `sort_order`, `is_published`, `translations`, `created_at`, `updated_at`) VALUES ('3', 'What languages will be available?', 'The conference will be held in English with simultaneous translation available in Hungarian, German, Romanian, and Russian. Translation devices will be provided at the venue.', 'general', '4', '1', NULL, '2026-01-27 13:55:25', '2026-02-20 15:24:46');
INSERT INTO `faqs` (`id`, `question`, `answer`, `category`, `sort_order`, `is_published`, `translations`, `created_at`, `updated_at`) VALUES ('4', 'Is childcare available?', 'Yes, we will have a supervised children''s program for ages 4-12 during main sessions. Registration for childcare is required in advance. Children under 4 must be accompanied by a parent or guardian.', 'general', '5', '1', NULL, '2026-01-27 13:55:25', '2026-02-20 15:24:46');
INSERT INTO `faqs` (`id`, `question`, `answer`, `category`, `sort_order`, `is_published`, `translations`, `created_at`, `updated_at`) VALUES ('5', 'Are meals included?', 'Meals are not included in the registration fee. However, there will be food vendors on-site, and the venue is surrounded by restaurants and cafes. We''ll also have a coffee shop area for fellowship during breaks.', 'general', '6', '1', NULL, '2026-01-27 13:55:25', '2026-02-20 15:24:46');
INSERT INTO `faqs` (`id`, `question`, `answer`, `category`, `sort_order`, `is_published`, `translations`, `created_at`, `updated_at`) VALUES ('6', 'How do I apply to Volunteer?', 'Volunteer applications are open! Complete our application form and tell us how you would like to serve. Approved volunteers receive a 20% discount on the ticket and a free event t-shirt. Applications close September 1, 2026.', 'volunteer', '7', '1', NULL, '2026-01-27 13:55:25', '2026-02-20 15:24:46');
INSERT INTO `faqs` (`id`, `question`, `answer`, `category`, `sort_order`, `is_published`, `translations`, `created_at`, `updated_at`) VALUES ('7', 'Where can I stay if I''m coming for multiple days?', 'Budapest offers a wide range of accommodation options to suit every budget. From affordable hostels and Airbnb apartments to hotels near the venue, you''ll find plenty of choices. We''ll share a list of recommended accommodations closer to the event.', 'general', '8', '1', NULL, '2026-02-06 17:39:08', '2026-02-20 15:24:46');
INSERT INTO `faqs` (`id`, `question`, `answer`, `category`, `sort_order`, `is_published`, `translations`, `created_at`, `updated_at`) VALUES ('8', 'Where is the conference held?', 'Europe Revival 2026 will be held at BOK Csarnok in Budapest, Hungary.
INSERT INTO `faqs` (`id`, `question`, `answer`, `category`, `sort_order`, `is_published`, `translations`, `created_at`, `updated_at`) VALUES ('10', 'How can I support the work of Iris?', 'If you would like to support the mission of Iris, you can find more information at iriskrakow.org. Your generosity helps bring light to the darkness, healing to the broken, and love to the unloved across Europe.', 'general', '10', '1', NULL, '2026-02-20 15:24:46', '2026-02-20 15:24:46');
