INSERT INTO `speakers` (`id`, `uuid`, `slug`, `name`, `title`, `organization`, `country`, `bio`, `photo_path`, `type`, `is_featured`, `sort_order`, `social_links`, `translations`, `created_at`, `updated_at`) VALUES ('1', '430bb215-f71e-42ac-881b-32991bb52cb3', 'heidi-baker', 'Heidi Baker', 'Missionary', 'Co-founder Iris Global', 'United States', 'Heidi''s greatest passion is to live in the manifest presence of God and to carry His glory, presence and love to His body and a lost and dying world. Rolland and Heidi Baker founded Iris Ministries, now Iris Global, in 1980. In 1995, they were called to the poorest country in the world at the time, Mozambique, and faced an extreme test of the Gospel. They began by pouring out their lives among abandoned street children, and as the Holy Spirit moved miraculously, a revival movement spread throughout Mozambique''s ten provinces. Heidi is now "Mama Aida" to thousands of people, overseeing a broad holistic ministry including Bible schools, medical clinics, church-based orphan care, and a network of thousands of churches.', 'images/speakers/heidi-baker.webp', 'speaker', '1', '2', NULL, NULL, '2026-01-27 13:55:25', '2026-03-18 10:09:36');
INSERT INTO `speakers` (`id`, `uuid`, `slug`, `name`, `title`, `organization`, `country`, `bio`, `photo_path`, `type`, `is_featured`, `sort_order`, `social_links`, `translations`, `created_at`, `updated_at`) VALUES ('2', '008157f7-efff-40bb-8214-44db3b42244d', 'mel-tari', 'Mel Tari', 'Evangelist', 'Author, Like a Mighty Wind', 'Indonesia', 'Indonesian born Mel Tari—affectionately known as "Papa Mel"—is a general of the faith. With a passionate zeal for God, Papa Mel is a sent out one that sprinkles the nations—and in turn—sends out masses into the harvest field, stoking the fires of revival through empowering, championing, divinely connecting, and building up the body. As the "Papa", he has been speaking at Iris Europe camps since their inception in 2021. Papa Mel is the author of "Like a Mighty Wind" that has inspired millions across the world.', 'images/speakers/Mel-Tari-1.webp', 'speaker', '1', '1', NULL, NULL, '2026-01-27 13:55:25', '2026-03-18 10:02:32');
INSERT INTO `speakers` (`id`, `uuid`, `slug`, `name`, `title`, `organization`, `country`, `bio`, `photo_path`, `type`, `is_featured`, `sort_order`, `social_links`, `translations`, `created_at`, `updated_at`) VALUES ('3', '1abd95e5-f08e-4866-b4c5-69e344f48c54', 'david-gava', 'David Gava', 'Missionary', 'Co-founder Kerusso', 'Sweden', 'David is originally from Zimbabwe, currently resides in Sweden with his wife Ingela and their two children. He is a missionary and founder of Kerusso Ministry in Sweden and Kerusso School in Brazil, which he leads alongside his family. He has spent more than two decades carrying a powerful testimony of resurrection and healing from a severe speech impediment that made public speaking a challenge until age 21—he is living proof that with God nothing is impossible. He is a servant leader, bathed in humility and gentleness, with wisdom from the King to lead an army of revivalists across the nations!', 'images/speakers/david-gava.webp', 'workshop_leader', '1', '2', NULL, NULL, '2026-01-27 13:55:25', '2026-03-18 10:09:36');
INSERT INTO `speakers` (`id`, `uuid`, `slug`, `name`, `title`, `organization`, `country`, `bio`, `photo_path`, `type`, `is_featured`, `sort_order`, `social_links`, `translations`, `created_at`, `updated_at`) VALUES ('4', '13768c16-1748-48a8-9b0a-45480b491cbc', 'pastor-josef', 'Pastor Josef', 'Guest Speaker', 'Budapest Church', 'Hungary', 'Pastor Josef leads one of Budapest''s vibrant churches and is a key voice in the Hungarian Christian community.', 'images/speakers/pastor-josef.webp', 'speaker', '0', '4', NULL, NULL, '2026-01-27 13:55:25', '2026-02-20 13:45:40');
INSERT INTO `speakers` (`id`, `uuid`, `slug`, `name`, `title`, `organization`, `country`, `bio`, `photo_path`, `type`, `is_featured`, `sort_order`, `social_links`, `translations`, `created_at`, `updated_at`) VALUES ('5', 'a42f6150-e520-4801-bf47-889cfb2dc0df', 'mary-pat-gokee', 'Mary Pat Gokee', 'Workshop Leader', 'Pastor, Frontlines Ministries International', 'United States', 'Mary Pat Gokee serves with Iris Global and leads prophetic arts workshops, combining creativity with the prophetic.', 'images/speakers/mary-pat-gokee.webp', 'workshop_leader', '0', '1', NULL, NULL, '2026-01-27 13:55:25', '2026-03-09 11:15:45');
INSERT INTO `speakers` (`id`, `uuid`, `slug`, `name`, `title`, `organization`, `country`, `bio`, `photo_path`, `type`, `is_featured`, `sort_order`, `social_links`, `translations`, `created_at`, `updated_at`) VALUES ('6', 'd88044c6-4794-47a2-bf44-7e2a57314989', 'katey-maddux', 'Katey Maddux', 'Workshop Leader', 'Founder, KBC & MWI', 'United States', 'Katey Maddux is a Kingdom builder and global leader dedicated to helping women walk in freedom, clarity, and bold obedience to God''s design for their lives and families. She is the Founder of Kingdom Business Collective, a global community for Christian women entrepreneurs and leaders, and Mighty Warrior International, a nonprofit focused on prevention, awareness, and strategic solutions in the fight against human trafficking and exploitation. Her work takes shape at the intersection of business, ministry, and global mission, with initiatives and partnerships across the U.S., Europe, Africa, and Asia.', 'images/speakers/Katey.webp', 'workshop_leader', '0', '12', NULL, NULL, '2026-01-27 13:55:25', '2026-02-04 19:41:18');
INSERT INTO `speakers` (`id`, `uuid`, `slug`, `name`, `title`, `organization`, `country`, `bio`, `photo_path`, `type`, `is_featured`, `sort_order`, `social_links`, `translations`, `created_at`, `updated_at`) VALUES ('7', '47e9d52c-bb0a-4961-8a55-56c7e79b8fd8', 'baoyan-lam', 'Baoyan Lam & Rudy Taslim', 'Workshop Leader', 'Founders Iris Singapore & Living Oaks', 'China', 'Baoyan Lam serves with Iris Asia and brings wisdom and practical teaching on family and parenting from a biblical perspective.', 'images/speakers/baoyan-lam.webp', 'speaker', '0', '11', NULL, NULL, '2026-01-27 13:55:25', '2026-03-09 11:17:25');
INSERT INTO `speakers` (`id`, `uuid`, `slug`, `name`, `title`, `organization`, `country`, `bio`, `photo_path`, `type`, `is_featured`, `sort_order`, `social_links`, `translations`, `created_at`, `updated_at`) VALUES ('8', '1a50a870-ecd8-4d44-951f-cc49378e6687', 'tineke-bouwman', 'Tineke Bouwman', 'Workshop Leader', 'Founder, Lighthouse Ministries', 'Netherlands', 'Tineke Bouwman is the founder and forerunner of Lighthouse Ministries in Rilland, the Netherlands. As a prophetic voice in this generation, she brings breakthrough and stirs fire in the hearts of those she ministers to—releasing destiny. Lighthouse is a ministry born from walking in God-given prophetic revelation. It is a Family Home (community-centered living for young adults); a house of prayer; a church; and a training center. What started with a simple yes has grown into a prophetic movement. Tineke has raised up a generation burning for Jesus who understand the value of intimate life with God. She works internationally as a counselor and trainer of leaders. A mother of five children (including a foster daughter) and eight grandchildren, she gratefully enjoys time at home with her family when she is not running with God among the nations.', 'images/speakers/tineke-bouwman.webp', 'workshop_leader', '0', '10', NULL, NULL, '2026-02-06 15:11:13', '2026-03-09 11:15:45');
INSERT INTO `speakers` (`id`, `uuid`, `slug`, `name`, `title`, `organization`, `country`, `bio`, `photo_path`, `type`, `is_featured`, `sort_order`, `social_links`, `translations`, `created_at`, `updated_at`) VALUES ('9', 'd529932b-e0dd-499d-9b2b-a7914b75290f', 'awakening-music', 'Awakening Music', 'Worship Team', NULL, NULL, NULL, 'images/speakers/awakening-music.webp', 'worship_team', '0', '1', NULL, NULL, '2026-02-20 13:55:42', '2026-02-20 14:05:49');
