INSERT INTO `workshops` (`id`, `uuid`, `slug`, `title`, `short_description`, `description`, `benefits`, `speaker_id`, `image_path`, `capacity`, `duration_minutes`, `difficulty_level`, `requirements`, `is_published`, `sort_order`, `translations`, `created_at`, `updated_at`, `leader_name`, `schedule_note`, `date`) VALUES ('6', 'cb8d985c-e057-47e7-9610-114dc4362771', 'power-evangelism', 'Power Evangelism', 'Learn to step out in boldness and share the Gospel with signs and wonders following.', 'David Gava shares from years of front-line experience in power evangelism across nations. Learn how to hear the Holy Spirit for words of knowledge on the streets, pray for the sick, and lead people to Jesus with confidence and compassion.', NULL, '3', NULL, NULL, '90', 'all', NULL, '1', '2', NULL, '2026-02-06 16:19:50', '2026-03-13 12:59:00', 'David Gava', 'Saturday', '2026-10-23');
INSERT INTO `workshops` (`id`, `uuid`, `slug`, `title`, `short_description`, `description`, `benefits`, `speaker_id`, `image_path`, `capacity`, `duration_minutes`, `difficulty_level`, `requirements`, `is_published`, `sort_order`, `translations`, `created_at`, `updated_at`, `leader_name`, `schedule_note`, `date`) VALUES ('8', '2cdb39a8-1b7f-4a2e-824f-b0ca1145b0d3', 'prophetic-arts', 'Prophetic Arts', 'Express worship and prophetic revelation through creative arts and visual media.', 'Discover how to tap into the creative flow of the Holy Spirit. This hands-on workshop explores painting, drawing, and other visual arts as expressions of worship and prophetic revelation.', NULL, '15', NULL, NULL, '90', 'all', NULL, '1', '8', NULL, '2026-02-06 16:19:50', '2026-03-13 12:59:00', 'Dr. Kate', 'Saturday & Sunday', '2026-10-23');
INSERT INTO `workshops` (`id`, `uuid`, `slug`, `title`, `short_description`, `description`, `benefits`, `speaker_id`, `image_path`, `capacity`, `duration_minutes`, `difficulty_level`, `requirements`, `is_published`, `sort_order`, `translations`, `created_at`, `updated_at`, `leader_name`, `schedule_note`, `date`) VALUES ('9', '9cf7c23f-0703-4aec-87c6-6f15aa646954', 'prophetic-ministry', 'Prophetic', 'Grow in the prophetic gift and learn to minister with accuracy and love.', 'Tineke Bouwman, a seasoned prophetic voice, teaches how to hear God''s voice clearly, deliver prophetic words with accuracy and love, and grow in this vital gift for the building up of the body of Christ.', NULL, '8', NULL, NULL, '90', 'all', NULL, '1', '10', NULL, '2026-02-06 16:19:50', '2026-03-13 12:59:00', 'Tineke Bouwman', 'Saturday & Sunday', '2026-10-23');
INSERT INTO `workshops` (`id`, `uuid`, `slug`, `title`, `short_description`, `description`, `benefits`, `speaker_id`, `image_path`, `capacity`, `duration_minutes`, `difficulty_level`, `requirements`, `is_published`, `sort_order`, `translations`, `created_at`, `updated_at`, `leader_name`, `schedule_note`, `date`) VALUES ('11', '5ce95aaa-0692-4020-8298-148fdd5c46bd', 'missions', 'Missions', 'Catch a vision for global missions and learn practical steps to answer the call.', 'Mary Pat Gokee shares from her experience with Iris Global to inspire and equip you for cross-cultural missions, whether short-term or long-term. Learn about the harvest fields and how you can participate.', NULL, '5', NULL, NULL, '90', 'all', NULL, '1', '1', NULL, '2026-02-06 16:19:50', '2026-03-13 12:59:00', 'Mary Pat Gokee', 'Saturday & Sunday', '2026-10-23');
INSERT INTO `workshops` (`id`, `uuid`, `slug`, `title`, `short_description`, `description`, `benefits`, `speaker_id`, `image_path`, `capacity`, `duration_minutes`, `difficulty_level`, `requirements`, `is_published`, `sort_order`, `translations`, `created_at`, `updated_at`, `leader_name`, `schedule_note`, `date`) VALUES ('12', '29d7760f-b562-454f-9b15-bba7ab3eb39e', 'marketplace-missions', 'Marketplace Missions', 'Transform your workplace into a mission field and integrate faith with business.', 'Yan & Rudy share how to carry the Kingdom of God into the marketplace. Discover how your business and professional skills can be used for eternal impact and how to be a missionary wherever you work.', NULL, '13', NULL, NULL, '90', 'all', NULL, '1', '6', NULL, '2026-02-06 16:19:50', '2026-03-13 12:59:00', 'Yan & Rudy', 'Saturday & Sunday', '2026-10-23');
INSERT INTO `workshops` (`id`, `uuid`, `slug`, `title`, `short_description`, `description`, `benefits`, `speaker_id`, `image_path`, `capacity`, `duration_minutes`, `difficulty_level`, `requirements`, `is_published`, `sort_order`, `translations`, `created_at`, `updated_at`, `leader_name`, `schedule_note`, `date`) VALUES ('13', 'd5f0d064-85fe-4e2a-931f-3f60c5df0590', 'family', 'Family', 'Biblical foundations for building strong, God-centered families in today''s world.', 'Baoyan Lam brings wisdom and practical teaching on family and parenting from a biblical perspective. Learn how to build a God-honoring family culture and raise children who love Jesus.', NULL, '11', NULL, NULL, '90', 'all', NULL, '1', '4', NULL, '2026-02-06 16:19:50', '2026-03-13 12:59:00', 'Baoyan Lam', 'Saturday & Sunday', '2026-10-23');
